def solve_pair(gi,go):
    H,W=len(gi),len(go[0])
    cnt=Counter(x for r in gi for x in r); bg=cnt.most_common(1)[0][0]
    cc=Counter(v for r in range(H) for c in range(W) if gi[r][c]!=bg for v in [gi[r][c]])
    rarest=min(cc,key=lambda k:(cc[k],k)); sc=rarest
    others=[v for v,_ in cc.items() if v!=sc and v!=bg]
    pc=others[0]
    pp=[(r,c) for r in range(H) for c in range(W) if gi[r][c]==pc]
    ps=[(r,c) for r in range(H) for c in range(W) if gi[r][c]==sc]
    pset={(r-min(p[0] for p in pp),c-min(p[1] for _,p2 in [(p,p) for p in []])) for r,c in pp}
    # normalize bbox
    rs=[p[0] for p in pp]; cs=[p[1] for p in pp]
    pnorm={(r-min(rs),c-min(cs)) for r,c in pp}
    pmax=(max(r-min(rs) for r,_ in pnorm),max(c-min(cs) for _,c in pnorm))
    extra={(r,c) for r in range(H) for c in range(W) if go[r][c]==sc}-{set(ps)}
    target=extra
    # candidate offsets: stamp wholly inside extras OR seeds, with cells landing on extras/seeds only
    cands=[]
    for dr in range(-H,H+1):
        for dc in range(-W,W+1):
            cells=[(r+dr,c+dc) for r,c in pnorm]
            if all(0<=rr<H and 0<=cc<W and (rr,cc) in (extra|set(ps)) for rr,cc in cells):
                cands.append((dr,dc))
    sols=[]
    def bt(rem,path):
        if not rem:
            sols.append(path[:]); return True
        r,c=min(rem)
        found=False
        for pr,pc in pnorm:
            off=(r-pr,c-pc)
            cov={(rr+off[0],cc+off[1]) for rr,cc in pnorm}
            if any(k not in rem for k in cov): continue
            if all((rr,cc) in extra|set(ps) for rr,cc in cov):
                rem2=set(rem)-cov
                bt(rem2,path+[off]); found=True
        return found
    bt(target,set())
    return sols, len(sols)

